  NOT_FOUND: 'Not found.',
  RATE_LIMITED: 'Too many requests, try again shortly.',
  STORAGE_FAILED: 'Something went wrong on our end.',
} as const satisfies Record<ErrorKit.Code<typeof REGISTRY>, string>
