  switch (code) {
    case 'NOT_FOUND':
      return 'Not found.'
    case 'RATE_LIMITED':
      return 'Too many requests, try again shortly.'
    case 'STORAGE_FAILED':
      return 'Something went wrong on our end.'
    default: {
      const _exhaustive: never = code
      return _exhaustive
    }
  }
}
```

